package it.frociart.app;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import static it.frociart.app.FlowModel.*;
public final class FlowgorithmTests {
 static int checks;static void check(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static String text(Path p)throws Exception{return new String(Files.readAllBytes(p),StandardCharsets.UTF_8);}
 static String run(Document d,String[] inputs){FlowEngine.Runner r=new FlowEngine.Runner(d);int at=0;for(int i=0;i<10000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){if(r.state==FlowEngine.State.WAITING){check(at<inputs.length,"Input available");r.submitInput(inputs[at++]);}else r.step();}check(r.state==FlowEngine.State.COMPLETED,"Completion: "+r.errorMessage);return String.join("|",r.output);}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),out=root.resolve("android");Files.createDirectories(out);
  for(String row:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] parts=row.split("\t",-1);Path source=root.resolve("fixtures/"+parts[0]+".fprg");String original=text(source);Document d=FlowgorithmImport.decode(original);String[] inputs=parts[2].isEmpty()?new String[0]:parts[2].split("\\|");check(run(d,inputs).equals(parts[1]),"Execution "+parts[0]);check(text(source).equals(original),"Original untouched");String encoded=FlowCodec.encode(d);check(!encoded.contains("PRIVATE_HISTORY_MARKER")&&!encoded.contains("PRIVATE_AUTHOR_MARKER"),"Metadata omitted");Files.write(out.resolve(parts[0]+".frociart"),encoded.getBytes(StandardCharsets.UTF_8));check(run(FlowCodec.decode(text(out.resolve(parts[0]+".frociart"))),inputs).equals(parts[1]),"Save/reopen "+parts[0]);check(run(FlowPseudocode.decode(FlowPseudocode.encode(d)),inputs).equals(parts[1]),"Pseudocode "+parts[0]);FlowAutoLayout.apply(d);check(run(d,inputs).equals(parts[1]),"Riordina "+parts[0]);Path pc=root.resolve("pc/"+parts[0]+".frociart");if(Files.exists(pc))check(run(FlowCodec.decode(text(pc)),inputs).equals(parts[1]),"Cross-platform file "+parts[0]);}
  try(DirectoryStream<Path> stream=Files.newDirectoryStream(root.resolve("fixtures"),"reject-*.fprg")){for(Path p:stream){if(p.getFileName().toString().equals("reject-newline.fprg")){Document accepted=FlowgorithmImport.decode(text(p));boolean noNewline=false;for(Node n:accepted.nodes)if(n.kind==OUTPUT)noNewline=!FlowOutput.newline(n.text);check(noNewline&&run(accepted,new String[0]).equals("1"),"Output continuation supported");continue;}if(p.getFileName().toString().equals("reject-reference-array-parameters.fprg")){Document accepted=FlowgorithmImport.decode(text(p));int arrays=0;for(Function f:accepted.functions)for(Parameter a:f.parameters)if(a.isArray){arrays++;check(a.byReference,"Imported array uses reference semantics");}check(accepted.version>=3&&arrays>0,"Complete reference-vector example supported");continue;}if(p.getFileName().toString().equals("reject-array-param.fprg")){Document accepted=FlowgorithmImport.decode(text(p));check(accepted.version==3&&accepted.functions.get(0).parameters.get(0).byReference&&accepted.functions.get(0).parameters.get(0).isArray,"Vector references explicitly supported");check(run(accepted,new String[0]).equals(""),"Unused reference function never executes");continue;}if(p.getFileName().toString().equals("reject-comment-size.fprg")){Document accepted=FlowgorithmImport.decode(text(p));boolean note=false;for(Node n:accepted.nodes)if(n.kind==NOTE&&n.text.length()==2049)note=true;check(accepted.version==4&&note,"Standalone note exceeds old attached-comment limit safely");continue;}boolean rejected=false;try{FlowgorithmImport.decode(text(p));}catch(IllegalArgumentException e){rejected=true;check(e.getMessage().contains("Flowgorithm"),"Localized diagnostic: "+p);}check(rejected,"Reject "+p);}}
  Document notes=FlowgorithmImport.decode(text(root.resolve("fixtures/notes.fprg")));java.util.List<String> standalone=new java.util.ArrayList<>();for(Node n:notes.nodes){if(n.kind==NOTE){standalone.add(n.text);for(Edge e:notes.edges)check(!e.from.equals(n.id)&&!e.to.equals(n.id),"Note outside executable connectors");}check(n.kind!=PROCESS,"No executable comment assignments");}check(notes.version==4&&standalone.equals(java.util.Arrays.asList("Prima nota","Seconda nota","Coda ramo","Coda ciclo","Fine programma")),"Every standalone comment retained in source order");System.out.println("FLOWGORITHM_ANDROID_CORE PASS checks="+checks);
 }
}
